  ?item wdt:P225 ?name ; wdt:P105 ?rank .
  OPTIONAL { ?item rdfs:label ?en FILTER(LANG(?en) = "en") }
  OPTIONAL { ?item rdfs:label ?sv FILTER(LANG(?sv) = "sv") }
  OPTIONAL { ?item skos:altLabel ?enAlt FILTER(LANG(?enAlt) = "en") }
  OPTIONAL { ?item skos:altLabel ?svAlt FILTER(LANG(?svAlt) = "sv") }
  OPTIONAL { ?item wdt:P1939 ?dyntaxa }
} GROUP BY ?name ?item ?rank ?en ?sv

SELECT ?name ?item ?syn ?synName ?prop WHERE {
  VALUES ?name { "Cyanistes caeruleus" "Poecile montanus" "Poecile palustris" "Periparus ater" "Lophophanes cristatus" "Linaria cannabina" "Chloris chloris" "Spinus spinus" "Coloeus monedula" "Curruca communis" "Astur gentilis" "Lyrurus tetrix" "Chroicocephalus ridibundus" }
  ?item wdt:P225 ?name .
  { ?item wdt:P1420 ?syn . BIND("P1420" AS ?prop) } UNION { ?item wdt:P566 ?syn . BIND("P566" AS ?prop) } UNION { ?syn wdt:P1420 ?item . BIND("P1420-inverse" AS ?prop) }
  ?syn wdt:P225 ?synName .
}

