SELECT ?name ?old ?p ?target ?targetName WHERE {
  VALUES ?name { "Parus montanus" "Corvus monedula" "Sylvia communis" "Larus ridibundus" "Parus caeruleus" "Carduelis chloris" "Parus palustris" }
  ?old wdt:P225 ?name .
  OPTIONAL { ?old ?p ?target . VALUES ?p { wdt:P31 wdt:P12763 wdt:P1366 wdt:P1420 } OPTIONAL { ?target wdt:P225 ?targetName } }
}
